One common source of vulnerabilities in Java web applications is the improper handling of user input when interacting with the operating system, which leads to **Command Injection**.

```java
import java.io.BufferedReader;
import java.io.InputStreamReader;

public class CommandExecutor {
    public void runTask(String userInput) {
        try {
            // This method is vulnerable to Command Injection because 
            // it concatenates raw user input directly into a shell command.
            // An attacker could input something like: "myfile.txt; rm -rf /"
            Process process = Runtime.getRuntime().exec("ls -l " + userInput);

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
***

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.List;
import java.util.ArrayList;

public class CommandExecutor {
    public void runTask(String userInput) {
        try {
            // To fix this, we avoid passing a single raw string to the shell.
            // Instead, we use ProcessBuilder and pass arguments as a List.
            // This ensures the OS treats 'userInput' as a literal argument 
            // rather than part of the executable command string.
            ProcessBuilder pb = new ProcessBuilder("ls", "-l", userInput);
            Process process = pb.start();

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
